import { h } from "@stencil/core";

export interface FormControlProps {
	/** The input id, used to map the input to the label */
	inputId: string;

	/** The size of the form control */
	size: "xsmall" | "small" | "medium" | "large";

	/** The label id, used to map the label to the input */
	labelId?: string;

	/** The label text (if the label slot isn't used) */
	label?: string;

	/** Whether or not a label slot has been provided. */
	hasLabelSlot?: boolean;

	/** Whether or not a label info slot has been provided. */
	hasLabelInfoSlot?: boolean;

	/** Whether or not a before slot has been provided. */
	hasFrontSlot?: boolean;
	hasRearSlot?: boolean;
	hasTrailingSlot?: boolean;
	hasElementSuffix?: boolean;

	/** The help text id, used to map the input to the help text */
	helpTextId?: string;

	/** The help text (if the help-text slot isn't used) */
	helpText?: string;

	/** Whether or not a help text slot has been provided. */
	hasHelpTextSlot?: boolean;

	/** Type of form element.  Input and Textarea contain custom styles. */
	source?: string;

	/** Element is focused. */
	hasFocus?: boolean;

	/** Element has a value. */
	hasValue?: boolean;

	/** Element has error state */
	hasError?: boolean;

	/** Element is disabled */
	isDisabled?: boolean;

	/** Element is required */
	isRequired?: boolean;

	/** A function that gets called when the label is clicked. */
	onLabelClick?: (event: MouseEvent) => void;

	/** Extra info such as character count text in textarea to render on the right side of the help text */
	renderHelpTextRight?: () => void;

	cssClasses?: object;

	tooltip?: string;
	tooltipId?: string;
	maxlength?: number;
}

const FormControl = (props: FormControlProps, children) => {
	const hasLabel = props.label ? true : props.hasLabelSlot;
	const hasFront = props.hasFrontSlot;
	const hasRear = props.hasRearSlot;
	const hasTrailing = props.hasTrailingSlot;
	const hasHelpText = props.helpText ? true : props.hasHelpTextSlot;
	const isTooltip = props.tooltip ? true : false;
	let cls = "form-control__input form-control__element";
	if (props.cssClasses && Object.keys(props.cssClasses).length > 0) {
		const cssCls = props.cssClasses;
		for (const prop in cssCls) {
			if (cssCls[prop]) {
				cls += ` ${prop}`;
			}
		}
	}

	const renderLabel = () => (
		<label
			part="label"
			id={props.labelId}
			class={`form-control__label${props.hasError ? " error" : ""} ${
				props.isDisabled ? " disabled" : ""
			}`}
			htmlFor={props.inputId}
			onClick={props.onLabelClick}
		>
			<span class="form-control__label-text">
				<slot name="label">{props.label}</slot>{" "}
				{props.isRequired && (
					<span part="asterisk" class="form-control-asterisk-required">
						*
					</span>
				)}
			</span>
			<slot name="label-suffix" />
		</label>
	);

	return (
		<div
			part="form-control"
			class={{
				"form-control": true,
				"form-control--xsmall": props.size === "xsmall",
				"form-control--small": props.size === "small",
				"form-control--medium": props.size === "medium",
				"form-control--large": props.size === "large",
				"form-control--has-label": !!hasLabel,
				"form-control--has-label-info": !!props.hasLabelInfoSlot,
				"form-control--has-front": !!hasFront,
				"form-control--has-rear": !!hasRear,
				"form-control--has-trailing": !!hasTrailing,
				"form-control--has-help-text": !!hasHelpText,
				"form-control--disabled": !!props.isDisabled,
				"form-control--tooltip-reference": !!isTooltip,
				"form-control--has-maxlength":
					props.maxlength !== undefined && props.maxlength > 0,
			}}
		>
			{hasLabel && props.hasLabelInfoSlot ? (
				<div part="label-container" class="form-control__label-container">
					{renderLabel()}
					<slot name="label-info" />
				</div>
			) : hasLabel ? (
				renderLabel()
			) : (
				""
			)}

			<div part="front" data-testid="front" class="form-control__front">
				<slot name="front" />
			</div>
			<div
				part="element"
				class={{
					[cls]: true,
					"form-control__element-wrapper": !!props.hasElementSuffix,
				}}
			>
				{children}
				<span part="element-suffix" class="form-control__element-suffix">
					<slot name="element-suffix" />
				</span>
			</div>
			<div
				part="trailing"
				data-testid="trailing"
				class="form-control__trailing"
			>
				<slot name="trailing" />
			</div>
			<div
				part="help-text"
				id={props.helpTextId}
				class={`form-control__help-text ${props.hasError ? " error" : ""}`}
				data-testid="helpText"
			>
				<slot name="help-text">{props.helpText}</slot>
				{props.renderHelpTextRight ? props.renderHelpTextRight() : null}
			</div>

			<div part="rear" data-testid="rear" class="form-control__rear">
				<slot name="rear" />
			</div>

			{props.tooltip ? (
				// biome-ignore lint/a11y/noInteractiveElementToNoninteractiveRole: <explanation>
				<hbr-visually-hidden role="tooltip" id={props.tooltipId}>
					{props.tooltip}
				</hbr-visually-hidden>
			) : null}
		</div>
	);
};

export default FormControl;
